import React from 'react';
import './logIn.css';
import foobarImage from './foobar.jpg';
import { useNavigate } from 'react-router-dom';



function LogIn() {
    const navigate = useNavigate();

    const handleSignupClick = () => {
      // Navigate to the signup page
      navigate('SignUp');
    };
    return (
        <header id="header">
        <div class="layer"></div>

        <div class="main">
            <div class="left">
            <img src={foobarImage} alt="" />
                <p>Connect with friends and the world around you on Foobar.</p>
            </div>
            <div class="right">
                <form action="#">
                    <div class="form_body">
                        <input type="text " placeholder="Email"></input>
                        <input type="password" placeholder="Password"></input>
                        <button class="login " onclick="feed()">Log In</button>
                        <p class="forget">forgot password?</p>
                        <hr></hr>
                        <button class="create" onClick={handleSignupClick}>Create new account</button>
                    </div>
                </form>
                <p class="foot"><span>Create a Page</span> for a celebrity, brand or business.</p>
            </div>
        </div>
        </header>

);
}

export default LogIn;
